# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See docs/REPARSE-CONTRACT.md
#
# Canonical form used for every comparison and for the report:
#   * full (rooted) path with '.' and '..' collapsed
#   * separators normalised to '\'
#   * no trailing directory separator, except for a volume root ('C:\')
#   * the caller's casing is preserved verbatim - canonicalisation is a purely
#     lexical operation and never touches the file system, so it neither
#     lower-cases nor expands short (8.3) names.

# Current file-system location, used only to expand a relative argument. It is
# never used to resolve a relative *link target*: those are resolved against
# the directory that contains the link.
function Get-WReparseCurrentLocation {
    [CmdletBinding()]
    param()
    try {
        $location = $ExecutionContext.SessionState.Path.CurrentFileSystemLocation
        if ($null -ne $location) {
            $providerPath = $location.ProviderPath
            if (-not [string]::IsNullOrEmpty($providerPath)) { return [string]$providerPath }
        }
    }
    catch { }
    try {
        if (-not [string]::IsNullOrEmpty($PWD.ProviderPath)) { return [string]$PWD.ProviderPath }
    }
    catch { }
    return [string][System.Environment]::CurrentDirectory
}

# Lexical canonicalisation. Returns $null when the string cannot be turned into
# a rooted path at all (empty, whitespace only, illegal characters, malformed
# UNC ...). Callers decide how to report that.
function Get-WReparseCanonicalPathOrNull {
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $candidate = [string]$Path

    # '\\?\' and '\??\' are NT namespace transport forms of the very same path.
    if ($candidate.Length -ge 4) {
        $head = $candidate.Substring(0, 4)
        if ($head -eq '\\?\' -or $head -eq '\??\') {
            $candidate = $candidate.Substring(4)
            if ($candidate.StartsWith('UNC\', [System.StringComparison]::OrdinalIgnoreCase)) {
                $candidate = '\' + $candidate.Substring(4)
            }
        }
    }

    if (-not [System.IO.Path]::IsPathRooted($candidate)) {
        $base = Get-WReparseCurrentLocation
        if (-not [string]::IsNullOrEmpty($base)) {
            $candidate = [System.IO.Path]::Combine($base, $candidate)
        }
    }

    $full = $null
    try { $full = [System.IO.Path]::GetFullPath($candidate) }
    catch { return $null }
    if ([string]::IsNullOrWhiteSpace($full)) { return $null }

    $full = $full.Replace([char]'/', [char]'\')

    # Strip trailing separators, but never mangle a volume root ('C:\').
    $isVolumeRoot = ($full.Length -eq 3) -and ($full[1] -eq [char]':') -and ($full[2] -eq [char]'\')
    if ((-not $isVolumeRoot) -and ($full.Length -gt 1)) {
        $full = $full.TrimEnd([char]'\')
    }
    if ([string]::IsNullOrEmpty($full)) { return $null }
    return $full
}

function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    $canonical = Get-WReparseCanonicalPathOrNull -Path $Path
    if ($null -eq $canonical) {
        throw [System.ArgumentException]::new("Path cannot be canonicalised: '$Path'", 'Path')
    }
    return $canonical
}

# Directory-boundary aware containment. 'C:\root2' is NOT inside 'C:\root' even
# though 'C:\root2'.StartsWith('C:\root') is true, so the prefix has to be
# terminated by a separator. Windows path comparison is case-insensitive; the
# ordinal-ignore-case comparer is used so the answer never depends on the host
# culture (a culture-aware compare would order non-ASCII names differently).
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) {
        return $false
    }
    $child = Get-WReparseCanonicalPathOrNull -Path $Path
    $parent = Get-WReparseCanonicalPathOrNull -Path $Root
    if ($null -eq $child -or $null -eq $parent) { return $false }
    if ([string]::Equals($child, $parent, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    $prefix = $parent
    if (-not $prefix.EndsWith([string][char]'\', [System.StringComparison]::Ordinal)) {
        $prefix = $prefix + '\'
    }
    return [bool]$child.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

# The reparse target stored on disk may be relative. A relative target is
# resolved against the directory that CONTAINS the link - never against the
# process working directory and never against the scan root. The result is
# purely lexical: a dangling link still resolves to the path it points at.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$LinkFullPath,
        [AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    $raw = ([string]$RawTarget).Trim()
    if ($raw.Length -eq 0) { return $null }

    # Volume GUID paths ('\\?\Volume{...}\') are kept in their namespace form.
    if ($raw.StartsWith('\??\Volume{', [System.StringComparison]::OrdinalIgnoreCase) -or
        $raw.StartsWith('\\?\Volume{', [System.StringComparison]::OrdinalIgnoreCase)) {
        return [string]('\\?\' + $raw.Substring(4).TrimEnd([char]'\'))
    }

    $candidate = $raw
    if ([System.IO.Path]::IsPathRooted($candidate)) {
        # rooted: '\??\C:\x', '\\?\C:\x', 'C:\x', '\\server\share\x'
    }
    else {
        $linkDirectory = $null
        if (-not [string]::IsNullOrWhiteSpace($LinkFullPath)) {
            $canonicalLink = Get-WReparseCanonicalPathOrNull -Path $LinkFullPath
            if ($null -ne $canonicalLink) {
                try { $linkDirectory = [System.IO.Path]::GetDirectoryName($canonicalLink) }
                catch { $linkDirectory = $null }
            }
        }
        if ([string]::IsNullOrEmpty($linkDirectory)) {
            $linkDirectory = Get-WReparseCurrentLocation
        }
        try { $candidate = [System.IO.Path]::Combine($linkDirectory, $raw) }
        catch { return $null }
    }

    return Get-WReparseCanonicalPathOrNull -Path $candidate
}

# Stable ordering key: ordinal, case-insensitive first, with a case-sensitive
# tie-break so that two entries whose names differ only by case keep a
# deterministic position. This is exactly the order that NTFS itself uses and
# that the observed provider facts require; it is identical under en-US, de-DE
# and ja-JP because no culture-aware collation is involved at all.
function Compare-WReparsePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Left,
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Right
    )
    $leftValue = [string]$Left
    $rightValue = [string]$Right
    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($leftValue, $rightValue)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($leftValue, $rightValue)
}

# WReparse - directory walker
# Safe directory enumeration: reparse classification, containment, cycle and
# depth control. Part of the WReparse implementation.
# See docs/REPARSE-CONTRACT.md and ../assets/observed-provider-facts.json
#
# Ground rules that the walk has to honour:
#   * the scan root itself is never emitted as a record; its children are at
#     depth 1, and depth grows by one per level;
#   * a directory whose own depth already reached -MaxDepth is NOT enumerated;
#     a single 'too_deep' error is recorded against it. -MaxDepth below zero is
#     clamped to 0, which makes '-MaxDepth -1' byte-identical to '-MaxDepth 0';
#   * without -Follow no reparse point is ever entered (each one is counted in
#     Stats.Skipped) and no cycle/broken_target probing happens at all;
#   * with -Follow a reparse point is entered under the NAME OF THE LINK, not
#     under the real target path; only a target that is an ancestor of the
#     current branch is a cycle - two sibling links pointing at the same
#     directory are not;
#   * entries are classified by the FILE_ATTRIBUTE_REPARSE_POINT bit, never by
#     the provider's LinkType: a hard link has a LinkType but no reparse bit and
#     is therefore an ordinary file.

# FILE_ATTRIBUTE_REPARSE_POINT
$script:WReparseAttributeReparsePoint = 0x400

function Get-WReparseMemberValue {
    [CmdletBinding()]
    param(
        [AllowNull()]$InputObject,
        [Parameter(Mandatory = $true)][string]$Name
    )
    if ($null -eq $InputObject) { return $null }
    $psObject = $InputObject.PSObject
    if ($null -eq $psObject) { return $null }
    $property = $psObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    try { return $property.Value }
    catch { return $null }
}

# The provider reports LinkType for hard links too ('HardLink'), but hard links
# are not reparse points, so this mapping is only ever reached for entries that
# do carry the reparse attribute. Junction and SymbolicLink stay distinct.
function Get-WReparseKindFromLinkType {
    [CmdletBinding()]
    param([AllowNull()][string]$LinkType)
    switch ([string]$LinkType) {
        'SymbolicLink' { return 'SymbolicLink' }
        'Junction' { return 'Junction' }
        'MountPoint' { return 'MountPoint' }
        'HardLink' { return 'HardLink' }
        '' { return 'Unknown' }
        default { return [string]$LinkType }
    }
}

function Test-WReparseIsReparsePoint {
    [CmdletBinding()]
    param([AllowNull()]$Item)
    $attributes = Get-WReparseMemberValue -InputObject $Item -Name 'Attributes'
    if ($null -eq $attributes) { return $false }
    return (([int]$attributes -band $script:WReparseAttributeReparsePoint) -ne 0)
}

function Test-WReparseIsContainer {
    [CmdletBinding()]
    param([AllowNull()]$Item)
    $isContainer = Get-WReparseMemberValue -InputObject $Item -Name 'PSIsContainer'
    if ($null -eq $isContainer) { return $false }
    return [bool]$isContainer
}

# The provider hands out .Target as a collection (System.String[] for links, a
# List[string] for hard links) and PowerShell unrolls a single-element array when
# it is returned from a helper, so the runtime type of a forwarded .Target would
# depend on the number of targets. The report always stores a string: one target
# is stored verbatim, several targets are joined with ';'.
function Get-WReparseRawTargetString {
    [CmdletBinding()]
    param([AllowNull()]$Target)
    if ($null -eq $Target) { return $null }
    if ($Target -is [string]) {
        $single = [string]$Target
        if ($single.Length -eq 0) { return $null }
        return $single
    }
    $elements = @($Target)
    if ($elements.Count -eq 0) { return $null }
    $parts = New-Object System.Collections.ArrayList
    foreach ($element in $elements) {
        if ($null -ne $element) {
            $text = [string]$element
            if ($text.Length -gt 0) { [void]$parts.Add($text) }
        }
    }
    if ($parts.Count -eq 0) { return $null }
    return [string]::Join(';', [string[]]$parts.ToArray())
}

function Test-WReparseIsAncestor {
    [CmdletBinding()]
    param(
        [AllowNull()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    if ($null -eq $Ancestry) { return $false }
    foreach ($ancestor in $Ancestry) {
        if ($null -eq $ancestor) { continue }
        if ([string]::Equals([string]$ancestor, $Path, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function Add-WReparseError {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Code,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message
    )
    [void]$State.Errors.Add((New-WReparseError -RelativePath $RelativePath -Code $Code -Message $Message))
}

# '.' is the contractual relative path of the scan root itself.
function Get-WReparseDisplayRelativePath {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowEmptyString()][string]$RelativePath)
    if ([string]::IsNullOrEmpty($RelativePath)) { return '.' }
    return $RelativePath
}

function Invoke-WReparseDirectoryWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$RealDirectory,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$VirtualRelative,
        [Parameter(Mandatory = $true)][int]$Depth,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][hashtable]$State
    )

    if ($Depth -ge $State.MaxDepth) {
        Add-WReparseError -State $State `
            -RelativePath (Get-WReparseDisplayRelativePath -RelativePath $VirtualRelative) `
            -Code 'too_deep' `
            -Message "Depth limit of $($State.MaxDepth) reached; not enumerating."
        return
    }

    $children = @()
    try {
        $children = @(Get-ChildItem -LiteralPath $RealDirectory -Force -ErrorAction Stop)
    }
    catch {
        Add-WReparseError -State $State `
            -RelativePath (Get-WReparseDisplayRelativePath -RelativePath $VirtualRelative) `
            -Code 'access_denied' `
            -Message ('Directory could not be enumerated: ' + [string]$_.Exception.Message)
        return
    }

    foreach ($child in $children) {
        if ($null -eq $child) { continue }

        $name = [string](Get-WReparseMemberValue -InputObject $child -Name 'Name')
        $childFull = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        if ([string]::IsNullOrEmpty($name)) {
            if ([string]::IsNullOrEmpty($childFull)) { continue }
            $name = [string]$childFull
        }
        $childDepth = $Depth + 1
        if ([string]::IsNullOrEmpty($VirtualRelative)) {
            $childRelative = $name
        }
        else {
            $childRelative = $VirtualRelative + '\' + $name
        }

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = Get-WReparseRawTargetString -Target (Get-WReparseMemberValue -InputObject $child -Name 'Target')
            $resolved = Resolve-WReparseLinkTarget -LinkFullPath $childFull -RawTarget $rawTarget

            $inScope = $false
            if ($null -ne $resolved) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }

            [void]$State.Records.Add((New-WReparseRecord `
                -RelativePath $childRelative `
                -Kind $script:WReparseKindReparse `
                -ReparseKind (Get-WReparseKindFromLinkType -LinkType $linkType) `
                -Target $rawTarget `
                -ResolvedTarget $resolved `
                -InScope $inScope `
                -Depth $childDepth `
                -Size 0))

            if (-not $State.Follow) {
                # Registered but never entered; no probing of the target either,
                # so a dangling or looping target produces no error at all.
                $State.Skipped = [int]$State.Skipped + 1
                continue
            }

            if ($null -eq $resolved) {
                Add-WReparseError -State $State -RelativePath $childRelative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }

            $exists = $false
            $isContainer = $false
            try {
                $exists = [bool](Test-Path -LiteralPath $resolved)
                if ($exists) { $isContainer = [bool](Test-Path -LiteralPath $resolved -PathType Container) }
            }
            catch {
                $exists = $false
                $isContainer = $false
            }

            if (-not $exists) {
                Add-WReparseError -State $State -RelativePath $childRelative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }
            if (-not $isContainer) {
                # A link onto a file is registered, but it has no children.
                continue
            }

            $targetCanonical = Get-WReparseCanonicalPathOrNull -Path $resolved
            if ($null -eq $targetCanonical) { $targetCanonical = $resolved }

            if (Test-WReparseIsAncestor -Ancestry $Ancestry -Path $targetCanonical) {
                Add-WReparseError -State $State -RelativePath $childRelative -Code 'cycle' `
                    -Message 'The reparse target is an ancestor already visited on this branch.'
                continue
            }

            # Entered under the link's own relative path, so every descendant is
            # named after the link and not after the real target.
            Invoke-WReparseDirectoryWalk -RealDirectory $targetCanonical -VirtualRelative $childRelative `
                -Depth $childDepth -Ancestry (@($Ancestry) + $targetCanonical) -State $State
            continue
        }

        $isContainer = Test-WReparseIsContainer -Item $child
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) {
                try { $size = [long]$length } catch { $size = [long]0 }
            }
        }

        $kind = if ($isContainer) { $script:WReparseKindDirectory } else { $script:WReparseKindFile }

        # InScope only means something for a reparse point (it says whether the
        # resolved target stays inside the scan root). Plain files and
        # directories are where they are, so they are always false.
        [void]$State.Records.Add((New-WReparseRecord `
            -RelativePath $childRelative `
            -Kind $kind `
            -ReparseKind $null `
            -Target $null `
            -ResolvedTarget $null `
            -InScope $false `
            -Depth $childDepth `
            -Size $size))

        if ($isContainer) {
            $childCanonical = Get-WReparseCanonicalPathOrNull -Path $childFull
            if ($null -eq $childCanonical) { $childCanonical = $childFull }
            Invoke-WReparseDirectoryWalk -RealDirectory $childCanonical -VirtualRelative $childRelative `
                -Depth $childDepth -Ancestry (@($Ancestry) + $childCanonical) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [bool]$Follow = $false,
        [int]$MaxDepth = 32
    )

    # '-MaxDepth -1' has to behave exactly like '-MaxDepth 0'.
    $effectiveMaxDepth = $MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $state = @{
        Records  = (New-Object System.Collections.ArrayList)
        Errors   = (New-Object System.Collections.ArrayList)
        Skipped  = 0
        Root     = [string]$Root
        Follow   = [bool]$Follow
        MaxDepth = [int]$effectiveMaxDepth
    }

    $canonicalRoot = Get-WReparseCanonicalPathOrNull -Path $Root
    if ($null -eq $canonicalRoot) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'invalid_argument' `
            -Message "Scan root cannot be canonicalised: $Root"
        return [pscustomobject]@{
            Root    = [string]$Root
            Records = [object[]]@()
            Errors  = [object[]]$state.Errors.ToArray()
            Skipped = 0
        }
    }
    $state.Root = $canonicalRoot

    if (-not (Test-Path -LiteralPath $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'not_found' `
            -Message "Scan root does not exist: $canonicalRoot"
        return [pscustomobject]@{
            Root    = $canonicalRoot
            Records = [object[]]@()
            Errors  = [object[]]$state.Errors.ToArray()
            Skipped = 0
        }
    }
    if (-not (Test-Path -LiteralPath $canonicalRoot -PathType Container)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'structure' `
            -Message "Scan root is not a directory: $canonicalRoot"
        return [pscustomobject]@{
            Root    = $canonicalRoot
            Records = [object[]]@()
            Errors  = [object[]]$state.Errors.ToArray()
            Skipped = 0
        }
    }

    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -VirtualRelative '' `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return [pscustomobject]@{
        Root    = $canonicalRoot
        Records = [object[]]$state.Records.ToArray()
        Errors  = [object[]]$state.Errors.ToArray()
        Skipped = [int]$state.Skipped
    }
}

# WReparse - report assembly
# Deterministic ordering, statistics and serialisation.
# Part of the WReparse implementation. See docs/REPARSE-CONTRACT.md
#
# Ordering must not depend on the host culture: Sort-Object is deliberately NOT
# used, because its default string comparison is culture-aware and would order
# non-ASCII names differently on en-US, de-DE and ja-JP hosts. Records are
# ordered by RelativePath with the ordinal-ignore-case comparer and an ordinal
# tie-break, which is the order the observed provider facts require and which is
# identical on every host.

$script:WReparseJsonDepth = 16

# OrderBy is a documented stable sort, so applying the lower priority key first
# and the higher priority key afterwards yields exactly
# "ordinal-ignore-case, then ordinal" without needing a custom comparer type.
function Get-WReparseSortedRecords {
    [CmdletBinding()]
    param([AllowEmptyCollection()][AllowNull()][object[]]$Items)
    $array = @($Items)
    if ($array.Count -eq 0) { return [object[]]@() }
    $keyPath = [Func[object, string]] { param($item) [string]$item.RelativePath }
    $byOrdinal = [System.Linq.Enumerable]::OrderBy([object[]]$array, $keyPath, [System.StringComparer]::Ordinal)
    $byPath = [System.Linq.Enumerable]::OrderBy($byOrdinal, $keyPath, [System.StringComparer]::OrdinalIgnoreCase)
    return [object[]][System.Linq.Enumerable]::ToArray($byPath)
}

# Errors are ordered by RelativePath (same comparer as the records), then by Code
# and Message, so that two runs over the same tree always emit them in the same
# order even when several errors share one path.
function Get-WReparseSortedErrors {
    [CmdletBinding()]
    param([AllowEmptyCollection()][AllowNull()][object[]]$Items)
    $array = @($Items)
    if ($array.Count -eq 0) { return [object[]]@() }
    $keyMessage = [Func[object, string]] { param($item) [string]$item.Message }
    $keyCode = [Func[object, string]] { param($item) [string]$item.Code }
    $keyPath = [Func[object, string]] { param($item) [string]$item.RelativePath }
    $byMessage = [System.Linq.Enumerable]::OrderBy([object[]]$array, $keyMessage, [System.StringComparer]::Ordinal)
    $byCode = [System.Linq.Enumerable]::OrderBy($byMessage, $keyCode, [System.StringComparer]::Ordinal)
    $byOrdinal = [System.Linq.Enumerable]::OrderBy($byCode, $keyPath, [System.StringComparer]::Ordinal)
    $byPath = [System.Linq.Enumerable]::OrderBy($byOrdinal, $keyPath, [System.StringComparer]::OrdinalIgnoreCase)
    return [object[]][System.Linq.Enumerable]::ToArray($byPath)
}

function Get-WReparseStats {
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][AllowNull()][object[]]$Records,
        [int]$Skipped = 0,
        [int]$ErrorCount = 0
    )
    $directories = 0
    $files = 0
    $reparse = 0
    foreach ($record in @($Records)) {
        if ($null -eq $record) { continue }
        switch ([string]$record.Kind) {
            'File' { $files++ }
            'Directory' { $directories++ }
            'ReparsePoint' { $reparse++ }
        }
    }
    return New-WReparseStats -Directories $directories -Files $files -ReparsePoints $reparse `
        -Skipped $Skipped -Errors $ErrorCount
}

function Get-WReparseReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )

    $walk = Invoke-WReparseWalk -Root $Root -Follow ([bool]$Follow) -MaxDepth $MaxDepth
    $records = @(Get-WReparseSortedRecords -Items ([object[]]$walk.Records))
    $errors = @(Get-WReparseSortedErrors -Items ([object[]]$walk.Errors))
    $stats = Get-WReparseStats -Records $records -Skipped ([int]$walk.Skipped) -ErrorCount $errors.Count

    return New-WReparseReport -Root ([string]$walk.Root) -Records ([object[]]$records) `
        -Errors ([object[]]$errors) -Stats $stats
}

function ConvertTo-WReparseJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Report
    )
    $json = ConvertTo-Json -InputObject $Report -Depth $script:WReparseJsonDepth
    $json = [string]$json
    # Windows PowerShell renders an empty collection across several lines; the
    # contract wants the compact '[]' form. A JSON string value can never
    # contain a raw newline (it is escaped), so this only ever rewrites the
    # structural whitespace of an empty array.
    $json = [System.Text.RegularExpressions.Regex]::Replace($json, '\[\s*\n\s*\]', '[ ]')
    return $json
}

# WReparse - path semantics
# Canonicalisation, directory-boundary containment, and link-target resolution.
# Part of the WReparse implementation. See docs/REPARSE-CONTRACT.md
#
# Canonical form used for every comparison and for the report:
#   * full (rooted) path with '.' and '..' collapsed
#   * separators normalised to '\'
#   * no trailing directory separator, except for a volume root ('C:\')
#   * the caller's casing is preserved verbatim - canonicalisation is a lexical
#     operation, so it never lower-cases a path and never asks the file system
#     for the 'real' spelling of a name.

# Current file-system location, used only to expand a relative argument. It is
# never used to resolve a relative *link target*: those are resolved against the
# directory that contains the link.
function Get-WReparseCurrentLocation {
    [CmdletBinding()]
    param()
    try {
        $location = $ExecutionContext.SessionState.Path.CurrentFileSystemLocation
        if ($null -ne $location) {
            $providerPath = $location.ProviderPath
            if (-not [string]::IsNullOrEmpty($providerPath)) { return [string]$providerPath }
        }
    }
    catch { }
    try {
        $pwdPath = $PWD.ProviderPath
        if (-not [string]::IsNullOrEmpty($pwdPath)) { return [string]$pwdPath }
    }
    catch { }
    return [string][System.Environment]::CurrentDirectory
}

# Lexical canonicalisation. Returns $null when the string cannot be turned into a
# rooted path at all (empty, whitespace only, illegal characters, malformed UNC,
# ...). Callers decide how to report that; the scan reports 'invalid_argument'.
function Get-WReparseCanonicalPathOrNull {
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $candidate = [string]$Path

    # '\\?\' and '\??\' are NT namespace transport forms of the very same path.
    if ($candidate.Length -ge 4) {
        $head = $candidate.Substring(0, 4)
        if ($head -eq '\\?\' -or $head -eq '\??\') {
            $candidate = $candidate.Substring(4)
            if ($candidate.StartsWith('UNC\', [System.StringComparison]::OrdinalIgnoreCase)) {
                $candidate = '\' + $candidate.Substring(4)
            }
        }
    }

    $isRooted = $false
    try { $isRooted = [System.IO.Path]::IsPathRooted($candidate) }
    catch { return $null }

    if (-not $isRooted) {
        $base = Get-WReparseCurrentLocation
        if (-not [string]::IsNullOrEmpty($base)) {
            try { $candidate = [System.IO.Path]::Combine($base, $candidate) }
            catch { return $null }
        }
    }

    $full = $null
    try { $full = [System.IO.Path]::GetFullPath($candidate) }
    catch { return $null }
    if ([string]::IsNullOrWhiteSpace($full)) { return $null }

    $full = $full.Replace([char]'/', [char]'\')

    # Strip trailing separators, but never mangle a volume root ('C:\').
    $isVolumeRoot = ($full.Length -eq 3) -and ($full[1] -eq [char]':') -and ($full[2] -eq [char]'\')
    if ((-not $isVolumeRoot) -and ($full.Length -gt 1)) {
        $full = $full.TrimEnd([char]'\')
    }
    if ([string]::IsNullOrEmpty($full)) { return $null }
    return $full
}

function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    $canonical = Get-WReparseCanonicalPathOrNull -Path $Path
    if ($null -eq $canonical) {
        throw (New-Object System.ArgumentException("Path cannot be canonicalised: '$Path'", 'Path'))
    }
    return $canonical
}

# Directory-boundary aware containment. 'C:\root2' is NOT inside 'C:\root' even
# though 'C:\root2'.StartsWith('C:\root') is true, so the prefix has to be
# terminated by a separator. Windows path comparison is case-insensitive; the
# ordinal-ignore-case comparer is used so the answer never depends on the host
# culture (a culture-aware compare would order non-ASCII names differently).
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) {
        return $false
    }
    $child = Get-WReparseCanonicalPathOrNull -Path $Path
    $parent = Get-WReparseCanonicalPathOrNull -Path $Root
    if ($null -eq $child -or $null -eq $parent) { return $false }
    if ([string]::Equals($child, $parent, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    $prefix = $parent
    if (-not $prefix.EndsWith([string][char]'\', [System.StringComparison]::Ordinal)) {
        $prefix = $prefix + '\'
    }
    return [bool]$child.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

# The reparse target stored on disk may be relative. A relative target is
# resolved against the directory that CONTAINS the link - never against the
# process working directory and never against the scan root. The result is
# purely lexical: a dangling link still resolves to the path it points at.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$LinkFullPath,
        [AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    $raw = ([string]$RawTarget).Trim()
    if ($raw.Length -eq 0) { return $null }

    # Volume GUID paths ('\\?\Volume{...}\') keep their namespace form.
    if ($raw.StartsWith('\??\Volume{', [System.StringComparison]::OrdinalIgnoreCase) -or
        $raw.StartsWith('\\?\Volume{', [System.StringComparison]::OrdinalIgnoreCase)) {
        return [string]('\\?\' + $raw.Substring(4).TrimEnd([char]'\'))
    }

    $candidate = $raw
    $isRooted = $false
    try { $isRooted = [System.IO.Path]::IsPathRooted($candidate) }
    catch { return $null }

    if (-not $isRooted) {
        $linkDirectory = $null
        if (-not [string]::IsNullOrWhiteSpace($LinkFullPath)) {
            $canonicalLink = Get-WReparseCanonicalPathOrNull -Path $LinkFullPath
            if ($null -ne $canonicalLink) {
                try { $linkDirectory = [System.IO.Path]::GetDirectoryName($canonicalLink) }
                catch { $linkDirectory = $null }
            }
        }
        if ([string]::IsNullOrEmpty($linkDirectory)) { $linkDirectory = Get-WReparseCurrentLocation }
        try { $candidate = [System.IO.Path]::Combine($linkDirectory, $raw) }
        catch { return $null }
    }

    return Get-WReparseCanonicalPathOrNull -Path $candidate
}

# Stable ordering key: ordinal, case-insensitive first, with a case-sensitive
# tie-break so that two entries whose names differ only by case keep a
# deterministic position. This is the order the observed provider facts require
# and it is identical under en-US, de-DE and ja-JP because no culture-aware
# collation is involved at all.
function Compare-WReparsePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Left,
        [Parameter(Mandatory = $true)][AllowEmptyString()][AllowNull()][string]$Right
    )
    $leftValue = [string]$Left
    $rightValue = [string]$Right
    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($leftValue, $rightValue)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($leftValue, $rightValue)
}
